/* Lot 109: rgb(), hsl(), hwb() and color(srgb) from origins outside the sRGB gamut, unclamped (generated by scripts/lot109_gen.py; expectations from scripts/lot109_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static char g_o[64];

/* 1, the 24-bit colour and the alpha (0..255) the reader paints, or 0 */
static const char *col(const char *v) {
    unsigned int rgb = 0;
    int a = 0;
    if (!wf_cssprop_color(v, (int)strlen(v), &rgb, &a)) return "0";
    snprintf(g_o, sizeof(g_o), "1 %06x %d", rgb, a);
    return g_o;
}

static void test_l109_ucol_0(void) {
    TEST_ASSERT_EQUAL_STRING("1 002710 255", col("hsl(from lab(50 -100 50) h s l)"));
    TEST_ASSERT_EQUAL_STRING("1 ffcfff 255", col("rgba(from oklch(0.85 0.19 269) 255 calc(g + 10) calc(b + 10))"));
    TEST_ASSERT_EQUAL_STRING("1 85fffa 255", col("rgba(from color(srgb 0.52 1.04 0.98) r calc(g + 20) b)"));
    TEST_ASSERT_EQUAL_STRING("1 00ff00 255", col("rgba(from lab(92 -111 93) r g b)"));
    TEST_ASSERT_EQUAL_STRING("1 656565 255", col("hwb(from color(a98-rgb 0.5 0.53 0.45) h w calc(b * 0.5 + 45))"));
    TEST_ASSERT_EQUAL_STRING("1 00f932 255", col("hsla(from color(prophoto-rgb -0.23 0.91 -0.22) h s calc(l * 0.5 + 45))"));
    TEST_ASSERT_EQUAL_STRING("1 00ad30 128", col("hsl(from color(display-p3 0.22 1.28 0.38) h s l / calc(alpha / 2))"));
    TEST_ASSERT_EQUAL_STRING("1 003bff 38", col("rgb(from color(prophoto-rgb -0.17 0.33 1.27 / 0.15) r calc(g * 0.5 + 1) b)"));
    TEST_ASSERT_EQUAL_STRING("1 00d2ff 255", col("rgba(from color(srgb -0.15 1.16 1.03) r calc(g - 45) b)"));
    TEST_ASSERT_EQUAL_STRING("1 ff0082 255", col("hwb(from color(rec2020 0.97 0.22 0.44) h w b)"));
    TEST_ASSERT_EQUAL_STRING("1 5227cb 255", col("rgba(from oklch(0.46 0.24 283) r g calc(b - 10) / alpha)"));
    TEST_ASSERT_EQUAL_STRING("1 3c80bc 255", col("rgba(from oklch(0.55 0.13 257) r 50% b / alpha)"));
    TEST_ASSERT_EQUAL_STRING("1 dafd00 41", col("hsl(from color(srgb-linear 0.94 1.19 0.08 / 0.16) h s calc(l - 20))"));
    TEST_ASSERT_EQUAL_STRING("1 ff0505 255", col("hsla(from color(srgb 1.12 -0.06 -0.24) h s calc(l + 1))"));
    TEST_ASSERT_EQUAL_STRING("1 45b138 255", col("color(from color(srgb 0.07 0.99 0.22) srgb calc(r + 0.2) calc(g * 0.5 + 0.2) b)"));
    TEST_ASSERT_EQUAL_STRING("1 3a322b 255", col("hsl(from lab(44 12 20) calc(h + 1) calc(s / 2) calc(l / 2) / alpha)"));
    TEST_ASSERT_EQUAL_STRING("1 f40074 255", col("hsla(from lab(64 108 29) h calc(s + 20) l)"));
    TEST_ASSERT_EQUAL_STRING("1 a8003c 255", col("color(from oklch(0.37 0.33 359) srgb r g b)"));
    TEST_ASSERT_EQUAL_STRING("1 ff96ba 255", col("hwb(from color(srgb 1.22 0.59 0.73) h w b)"));
    TEST_ASSERT_EQUAL_STRING("1 005c00 255", col("rgb(from color(srgb-linear 0.47 0.11 -0.14) 0 calc(g - 1) b)"));
}

